window.docContents[16].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/Hom_A_LPAR_Ae___-M_RPAR_-___-eM-for-idempotent-e-_LPAR_continues-to-missing-page_RPAR_/#Chapter5___Lemma5___13___4":{"contents":"Lemma 5.13.4. Let A be an algebra and let e be an idempotent in A. Then for any left A-module M, one has \\operatorname{Hom}_A(Ae, M) \\cong eM (namely, x \\in eM corresponds to f_x : Ae \\to M given by f_x(a) = ax, a \\in Ae).\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.13. Proof of the classification theorem for representations of $S_n$\tHom_A(Ae, M) ≅ eM for idempotent e (continues to missing page)","header":"Hom_A(Ae, M) ≅ eM for idempotent e (continues to missing page)","id":"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/Hom_A_LPAR_Ae___-M_RPAR_-___-eM-for-idempotent-e-_LPAR_continues-to-missing-page_RPAR_/#Chapter5___Lemma5___13___4"},"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Chapter6___Section6___3_heading___heading-1":{"contents":"As the last — slightly more complicated — example we consider the quiver D_4.\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.3. Indecomposable representations of the quiver $D_4$\tSection 6.3 heading and introduction","header":"6.3. Indecomposable representations of the quiver  D_4","id":"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Chapter6___Section6___3_heading___heading-1"},"/6___-Quiver-representations/6___6___-Reflection-functors/#chapter-06___section-6-6":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations","header":"6.6. Reflection functors","id":"/6___-Quiver-representations/6___6___-Reflection-functors/#chapter-06___section-6-6"},"/9___-Structure-of-finite-dimensional-algebras/9___1___-Lifting-of-idempotents/Lifting-complete-systems-of-orthogonal-idempotents/#Chapter9___Corollary9___1___3":{"contents":"Corollary 9.1.3. Let e_{01}, \\ldots, e_{0m} be a complete system of orthogonal idempotents in A/I. Then there exists a complete system of orthogonal idempotents e_1, \\ldots, e_m (e_i e_j = \\delta_{ij} e_i, \\sum e_i = 1) in A which lifts e_{01}, \\ldots, e_{0m}.\n\nProof. The proof is by induction in m. For m = 2 this follows from Proposition 9.1.1. For m > 2, we lift e_{01} to e_1 using Proposition 9.1.1 and then apply the induction assumption to the algebra (1 - e_1)A(1 - e_1). \\square\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.1. Lifting of idempotents\tLifting complete systems of orthogonal idempotents","header":"Lifting complete systems of orthogonal idempotents","id":"/9___-Structure-of-finite-dimensional-algebras/9___1___-Lifting-of-idempotents/Lifting-complete-systems-of-orthogonal-idempotents/#Chapter9___Corollary9___1___3"}});
